AcceptanceCriteria.AC-BASE-BYTE-INVARIANT:
        Relative to preservation base `3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df`, every base-tracked
        path outside the exact six product files and this bundle's exact own active/archive lifecycle
        directories is byte-identical, and no deleted or newly tracked path exists outside that allowed
        set. The instrument scans all base-tracked paths including both archive trees, checks the actual
        filesystem raw bytes and type/Git-mode against the base for every one of them — so a byte edited
        under `--assume-unchanged` or `--skip-worktree` still fails — and checks both unstaged and cached
        changes. Arbitrary untracked files outside the archive trees are not a new scope claim. It reads
        the exit code directly, never through a pipe, and fails closed on a missing base or a failed Git
        or filesystem read.
        git diff --exit-code 3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df -- . ':(exclude)skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)scripts/check-teaching-surface.ts' ':(exclude)scripts/check-teaching-surface.test.ts' ':(exclude)src/test-support/token-accounting.test.ts' ':(exclude)README.md' ':(exclude).ngrace/changes/active/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD' ':(exclude).ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD' && git diff --cached --exit-code 3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df -- . ':(exclude)skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)scripts/check-teaching-surface.ts' ':(exclude)scripts/check-teaching-surface.test.ts' ':(exclude)src/test-support/token-accounting.test.ts' ':(exclude)README.md' ':(exclude).ngrace/changes/active/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD' ':(exclude).ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD' && bun -e 'const {spawnSync}=require("node:child_process");
const fs=require("node:fs");
const crypto=require("node:crypto");
const BASE="3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df";
const OWN="C-PLANNING-PHASE-TEACHING-1-CBE5DFAD";
const ALLOWED=new Set(["skills/ngrace/ngrace-plan/SKILL.md","plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md","scripts/check-teaching-surface.ts","scripts/check-teaching-surface.test.ts","src/test-support/token-accounting.test.ts","README.md"]);
function fail(msg){console.error("GUARD-B FAIL: "+msg);process.exit(1);}
function dep(cmd,args){const r=spawnSync(cmd,args,{encoding:"buffer"});if(r.error){fail("dependency error "+cmd+": "+r.error.message);}if(r.status!==0){fail("dependency exit "+r.status+" "+cmd+" "+args.join(" ")+" :: "+r.stderr.toString().trim());}return r.stdout;}
function contentOf(p){const st=fs.lstatSync(p);if(st.isSymbolicLink())return Buffer.from(fs.readlinkSync(p));return fs.readFileSync(p);}
function blobSha(buf){return crypto.createHash("sha1").update(Buffer.concat([Buffer.from("blob "+buf.length+"\0"),buf])).digest("hex");}
function isOwn(p){const a=".ngrace/changes/active/"+OWN;const b=".ngrace/changes/archive/"+OWN;return p===a||p.startsWith(a+"/")||p===b||p.startsWith(b+"/");}
function allowed(p){return ALLOWED.has(p)||isOwn(p);}
const baseRaw=dep("git",["ls-tree","-r","-z",BASE]).toString("utf8");
const base=new Map();
for(const rec of baseRaw.split("\0")){if(rec.length===0)continue;const tab=rec.indexOf("\t");const meta=rec.slice(0,tab).split(" ");base.set(rec.slice(tab+1),{mode:meta[0],sha:meta[2]});}
const cur=dep("git",["ls-files","-z"]).toString("utf8").split("\0").filter(s=>s.length>0);
const curSet=new Set(cur);
const bad=[];
for(const [p,entry] of base){if(allowed(p))continue;if(!curSet.has(p)){bad.push("deleted "+p);continue;}let b;try{const st=fs.lstatSync(p);const mode=st.isSymbolicLink()?"120000":st.isFile()?((st.mode&0o100)?"100755":"100644"):"invalid";if(mode!==entry.mode){bad.push("mode/type "+p);continue;}b=contentOf(p);}catch(e){bad.push("unreadable "+p);continue;}if(blobSha(b)!==entry.sha)bad.push("byte "+p);}
for(const p of cur){if(allowed(p))continue;if(!base.has(p))bad.push("extra-tracked "+p);}
if(bad.length){fail(bad.slice(0,30).join("; "));}
console.log("GUARD-B OK tracked="+curSet.size);'

AcceptanceCriteria.AC-ARCHIVE-PRESERVATION:
        Every pre-existing byte and every pre-existing root/path under `.ngrace/changes/archive/` and
        `docs/plans/archive/` is unchanged against preservation base
        `3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df`. The instrument inventories the base Git paths and blob
        bytes and the actual filesystem entries under both archive trees, rejecting a missing, changed,
        or extra path, an ignored or untracked addition, and an added or missing root; it compares raw
        bytes and identities only and never parses XML, schema, or content. It skips exactly this bundle's
        own `.ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD` arrival, with the reason that the
        close itself renames the bundle directory into the archive and writes that arrived bundle's own
        post-archive verdict and `CloseEvidence`, so without the exclusion the close's own lawful arrival
        reddens the criterion it wrote; `docs/plans/archive/` has no exclusion. It retains the `git diff`
        guard and fails closed on a missing base or a failed Git or filesystem read. This is not a
        supersede, so no predecessor archive arrival is excluded.
        git diff --exit-code 3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df -- .ngrace/changes/archive docs/plans/archive ':(exclude).ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD' && bun -e 'const {spawnSync}=require("node:child_process");
const fs=require("node:fs");
const path=require("node:path");
const crypto=require("node:crypto");
const BASE="3d0bc291fd7b341aacbcdeb6d5176eb9f0d818df";
const OWN="C-PLANNING-PHASE-TEACHING-1-CBE5DFAD";
const ARCHS=[".ngrace/changes/archive","docs/plans/archive"];
function fail(msg){console.error("GUARD-A FAIL: "+msg);process.exit(1);}
function dep(cmd,args){const r=spawnSync(cmd,args,{encoding:"buffer"});if(r.error){fail("dependency error "+cmd+": "+r.error.message);}if(r.status!==0){fail("dependency exit "+r.status+" "+cmd+" "+args.join(" ")+" :: "+r.stderr.toString().trim());}return r.stdout;}
function contentOf(p){const st=fs.lstatSync(p);if(st.isSymbolicLink())return Buffer.from(fs.readlinkSync(p));if(!st.isFile())throw new Error("unsupported file type "+p);return fs.readFileSync(p);}
function blobSha(buf){return crypto.createHash("sha1").update(Buffer.concat([Buffer.from("blob "+buf.length+"\0"),buf])).digest("hex");}
const bad=[];
for(const ARCH of ARCHS){
  const raw=dep("git",["ls-tree","-r","-z",BASE,"--",ARCH]).toString("utf8");
  const base=new Map();
  const baseRoots=new Set();
  for(const rec of raw.split("\0")){if(rec.length===0)continue;const tab=rec.indexOf("\t");const meta=rec.slice(0,tab);const p=rec.slice(tab+1);base.set(p,meta.split(" ")[2]);const seg=p.slice(ARCH.length+1).split("/")[0];if(seg)baseRoots.add(seg);}
  function isOwn(p){return ARCH===".ngrace/changes/archive"&&p===ARCH+"/"+OWN;}
  for(const [p,sha] of base){if(!fs.existsSync(p)){bad.push("missing "+p);continue;}let b;try{b=contentOf(p);}catch(e){bad.push("unreadable "+p);continue;}if(blobSha(b)!==sha)bad.push("byte "+p);}
  const actual=[];
  function walk(d){for(const n of fs.readdirSync(d)){const p=path.join(d,n);if(isOwn(p))continue;const st=fs.lstatSync(p);if(st.isDirectory()){if(!Array.from(base.keys()).some(b=>b.startsWith(p+"/")))bad.push("extra-directory "+p);walk(p);}else actual.push(p);}}
  walk(ARCH);
  for(const p of actual){if(!base.has(p))bad.push("extra "+p);}
  const actualRoots=new Set();
  for(const n of fs.readdirSync(ARCH)){if(isOwn(ARCH+"/"+n))continue;actualRoots.add(n);}
  for(const r of baseRoots)if(!actualRoots.has(r))bad.push("root-missing "+r);
  for(const r of actualRoots)if(!baseRoots.has(r))bad.push("root-extra "+r);
}
if(bad.length){fail(bad.slice(0,30).join("; "));}
console.log("GUARD-A OK archives="+ARCHS.length);'
